begin;
do $test$
declare actor uuid:=gen_random_uuid();staff uuid:=gen_random_uuid();org uuid:=gen_random_uuid();s uuid:=gen_random_uuid();t uuid:=gen_random_uuid();batch uuid:=gen_random_uuid();run uuid:=gen_random_uuid();line uuid:=gen_random_uuid();req uuid:=gen_random_uuid();doc uuid:=gen_random_uuid();a jsonb;payload jsonb;result jsonb;before_doc jsonb;before_count integer;child uuid;original_account jsonb;child_account jsonb;
begin
 select count(*) into before_count from public.receipt_upload_batches;
 insert into auth.users(id,email,email_confirmed_at,created_at,updated_at) select id,id||'@receipt-store.invalid',now(),now(),now() from unnest(array[actor,staff]) id;
 insert into public.profiles(id,display_name) select id,'門市更正回滾測試' from unnest(array[actor,staff]) id on conflict(id) do nothing;
 insert into public.organizations(id,name,business_type) values(org,'門市更正回滾測試','SINGLE_RESTAURANT');
 insert into public.stores(id,organization_id,name,store_code,created_by) values(s,org,'BeApe','MV'||substr(s::text,1,8),actor),(t,org,'Gras','MV'||substr(t::text,1,8),actor);
 insert into public.organization_members(organization_id,user_id,role,is_owner,can_manage_business) values(org,actor,'OWNER',true,true),(org,staff,'STAFF',false,false);
 insert into public.staff_identities(organization_id,user_id,display_name,created_by) select org,id,'門市更正測試',actor from unnest(array[actor,staff]) id;
 insert into public.store_memberships(store_id,organization_id,user_id,login_identifier,role,work_role,assigned_by,can_manage_business) values(s,org,actor,'mv-owner','OWNER','OWNER',actor,true),(t,org,actor,'mv-owner-target','OWNER','OWNER',actor,true),(s,org,staff,'mv-staff','STAFF','STAFF',actor,false);
 insert into public.receipt_upload_batches(id,organization_id,store_id,store_name,uploaded_by,status,work_date) values(batch,org,s,'BeApe',actor,'READY_FOR_REVIEW',current_date);
 insert into public.receipt_ocr_runs(id,organization_id,batch_id,version,provider,model,prompt_version,status,started_by) values(run,org,batch,1,'manual','test','test','SUCCEEDED',actor);
 insert into private.receipt_manual_rows(id,batch_id,run_id,supplier_name,product_name,unit,quantity,unit_price_ex_tax,line_subtotal_ex_tax,created_by) values(line,batch,run,'測試廠商','測試麵粉','包',2,100,200,actor);
 insert into public.receipt_documents(id,organization_id,batch_id,storage_path,original_filename,page_order,mime_type,uploaded_by) values(doc,org,batch,'test/'||doc::text,'原貨單.jpeg',1,'image/jpeg',actor);
 select to_jsonb(d) into before_doc from public.receipt_documents d where id=doc;
 insert into storage.objects(bucket_id,name,metadata) values('receipt-documents','test/'||doc::text,'{"size":123,"mimetype":"image/jpeg"}');
 perform set_config('request.jwt.claim.sub',actor::text,true);

 a:=public.get_baihuayuan_receipt_accounts(s,null,null,null,batch)->0;
 original_account:=a;
 payload:=jsonb_build_object('revision',a->'revision','source_fingerprint',a->>'source_fingerprint','header',jsonb_build_object('supplier_name','第一家廠商','receipt_date',current_date,'document_number','FIRST'),'lines',a->'lines','adjustment',0,'tax',0,'total',200,'note','第一張備註','checked',false);
 begin perform public.create_receipt_same_photo(s,batch,payload||'{"revision":999999}',gen_random_uuid());raise exception 'stale accepted';exception when sqlstate 'PT409' or sqlstate '40001' then null;end;
 assert (select count(*)=before_count+1 from public.receipt_upload_batches),'stale created no child';
 update public.store_memberships set access_mode='VIEW' where store_id=s and user_id=actor;
 begin perform public.create_receipt_same_photo(s,batch,payload,req);raise exception 'readonly accepted';exception when sqlstate '42501' then null;end;
 update public.store_memberships set access_mode='EDIT' where store_id=s and user_id=actor;
 perform set_config('request.jwt.claim.sub',staff::text,true);
 begin perform public.create_receipt_same_photo(s,batch,payload,req);raise exception 'staff accepted';exception when sqlstate '42501' then null;end;
 perform set_config('request.jwt.claim.sub','',true);
 begin perform public.create_receipt_same_photo(s,batch,payload,req);raise exception 'anon accepted';exception when sqlstate '42501' then null;end;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 begin perform public.create_receipt_same_photo(t,batch,payload,req);raise exception 'other store accepted';exception when sqlstate '42501' then null;end;
 result:=public.create_receipt_same_photo(s,batch,payload,req);
 assert result=public.create_receipt_same_photo(s,batch,payload,req),'retry returns same child';
 child:=(result#>>'{account,batch_id}')::uuid;
 assert child<>batch,'separate accounting identity';
 assert (select count(*)=before_count+2 from public.receipt_upload_batches),'exactly one child';
 assert (select count(*)=1 from public.audit_logs where entity_id=child::text and action='receipt.same_photo.create'),'one audit';
 assert (select to_jsonb(d)=before_doc from public.receipt_documents d where id=doc),'source document unchanged';
 assert (select storage_path='test/'||doc::text from public.receipt_documents where batch_id=child),'same original path';
 assert jsonb_array_length(result#>'{account,lines}')=0,'no copied lines';
 assert coalesce(result#>>'{account,supplier_name}','')='','supplier blank';
 assert coalesce(result#>>'{account,tax}','')='','tax blank';
 assert coalesce(result#>>'{account,total}','')='','total blank';
 assert not exists(select 1 from public.receipt_ocr_jobs where batch_id=child),'no OCR job or quota usage';
 assert exists(select 1 from private.receipt_manual_handoffs where batch_id=child),'manual entry ready';
 original_account:=public.get_baihuayuan_receipt_accounts(s,null,null,null,batch)->0;
 assert original_account->>'supplier_name'='第一家廠商','source draft saved';
 child_account:=result->'account';
 payload:=jsonb_build_object('revision',child_account->'revision','source_fingerprint',child_account->>'source_fingerprint','header',jsonb_build_object('supplier_name','第二家廠商','receipt_date',current_date,'document_number','SECOND'),'lines',jsonb_build_array(jsonb_build_object('row_key','local-test','product_name','第二家商品','specification','','quantity',3,'unit','包','unit_price',10,'subtotal',30,'category','食材','note','')),'removed_row_keys','[]'::jsonb,'adjustment',0,'tax',2,'total',32,'note','第二張備註','checked',false);
 perform public.save_baihuayuan_receipt_entry(s,child,payload,gen_random_uuid());
 child_account:=public.get_baihuayuan_receipt_accounts(s,null,null,null,child)->0;
 assert child_account->>'supplier_name'='第二家廠商','independent supplier';
 assert (child_account->>'total')::numeric=32,'independent amount';
 assert jsonb_array_length(child_account->'lines')=1,'only second supplier item';
 assert public.get_baihuayuan_receipt_accounts(s,null,null,null,batch)->0=original_account,'child edits preserve first account';
 assert not exists(select 1 from public.goods_receipts where source_batch_id=child),'no stock posted by creating draft';
 assert not has_function_privilege('anon','public.create_receipt_same_photo(uuid,uuid,jsonb,uuid)','EXECUTE'),'anon RPC denied';
 perform set_config('request.jwt.claim.sub',staff::text,true);
 begin perform public.create_receipt_same_photo(s,batch,null,req);raise exception 'unauthorized retry accepted';exception when sqlstate '42501' then null;end;
end $test$;
rollback;
